const (
	TikTokPrivacyLevelPublicToEveryone    TikTokPrivacyLevel = "PUBLIC_TO_EVERYONE"
	TikTokPrivacyLevelMutualFollowFriends TikTokPrivacyLevel = "MUTUAL_FOLLOW_FRIENDS"
	TikTokPrivacyLevelFollowerOfCreator   TikTokPrivacyLevel = "FOLLOWER_OF_CREATOR"
	TikTokPrivacyLevelSelfOnly            TikTokPrivacyLevel = "SELF_ONLY"
)

func NewTikTokPrivacyLevelFromString(s string) (TikTokPrivacyLevel, error) {
	switch s {
	case "PUBLIC_TO_EVERYONE":
		return TikTokPrivacyLevelPublicToEveryone, nil
	case "MUTUAL_FOLLOW_FRIENDS":
		return TikTokPrivacyLevelMutualFollowFriends, nil
	case "FOLLOWER_OF_CREATOR":
		return TikTokPrivacyLevelFollowerOfCreator, nil
	case "SELF_ONLY":
		return TikTokPrivacyLevelSelfOnly, nil
	}
	var t TikTokPrivacyLevel
	return "", fmt.Errorf("%s is not a valid %T", s, t)
}

func (t TikTokPrivacyLevel) Ptr() *TikTokPrivacyLevel {
	return &t
}

